(()=>{
'use strict';
const {dest,hotels,prefs:defaults,rules}=TRIP;
const {rebalance,clone,evaluate,fromRoute,ranked,insertions,applyInsert,iso,activities,countryOrder}=AtlasModel;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const date=n=>new Date((n-25569)*86400000).toLocaleDateString('en-GB',{month:'short',day:'numeric',timeZone:'UTC'});
const safeURL=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}};
const link=(url,label)=>safeURL(url)?`<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
const ICON={sliders:'M4 7h7m4 0h5M4 17h3m4 0h9 M11 4v6m-4 4v6',bookmark:'M6 3h12v18l-6-4-6 4z',layers:'m3 9 9-5 9 5-9 5z M3 13l9 5 9-5 M3 17l9 5 9-5',calendar:'M4 6h16v15H4z M8 3v6m8-6v6 M4 11h16',plus:'M12 5v14M5 12h14',fit:'M4 9V4h5m6 0h5v5m0 6v5h-5m-6 0H4v-5',wallet:'M3 6h17v14H3z M3 6l13-3v3 M15 12h6v4h-6z',moon:'M19 15a8 8 0 0 1-10-10 8 8 0 1 0 10 10Z',sun:'M12 8a4 4 0 1 0 .01 0 M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z M12 7.5a2.5 2.5 0 1 0 .1 0',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M12 6v6l4 3',lock:'M6 10h12v10H6z M8 10V7a4 4 0 0 1 8 0v3'};
const icon=n=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${ICON[n]||''}"/></svg></span>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const best=TRIP.routes.find(r=>r.rank===1)||TRIP.routes[0],key='honeymoon-atlas.v1';
let state={draft:fromRoute(best),p:clone(defaults),saved:[]},tab='walk',selected=-1,m,ranking,adaptPins=false,dialogMode='',activeCat='Activities',query='',localOK=true,undoState=null,mix=null,insertList=[],swaps=[],suggestLimit=8,venueLimit=18;
const plan=()=>state.draft,stops=()=>plan().stops;
function validP(p){return p&&Array.isArray(p.activities)&&p.activities.length===defaults.activities.length&&p.activities.every(x=>Number.isFinite(x)&&x>=0&&x<=5)&&['budget','coast','maxStops','minStops','tokyo','resort','extras','timeWeight','budgetWeight','beachWeight','paceWeight','resortWeight'].every(k=>Number.isFinite(p[k])&&p[k]>=0)&&p.budget>0&&p.minStops<=p.maxStops&&['must','avoid'].every(k=>Array.isArray(p[k])&&p[k].every(c=>Object.hasOwn(dest,c)));}
function validDraft(d){return d&&TRIP.routes.some(r=>r.id===d.base)&&Array.isArray(d.stops)&&d.stops.length>1&&d.stops.length<=80&&d.stops[0].id==='BKK'&&d.stops.at(-1).id==='SEL'&&d.stops.every(s=>Object.hasOwn(dest,s.id)&&Number.isInteger(s.n)&&s.n>=1&&s.n<=80&&(!s.hotel||hotels[s.hotel]?.base===s.id)&&Array.isArray(s.picks)&&s.picks.every(id=>activities.get(id)?.base===s.id));}
try{const v=JSON.parse(localStorage.getItem(key)||'null');if(v&&validDraft(v.draft)&&validP(v.p)&&Array.isArray(v.saved))state={draft:v.draft,p:v.p,saved:v.saved.filter(s=>validDraft(s.draft)&&validP(s.p)&&typeof s.name==='string')};}catch{localOK=false;}
const msg=t=>{const el=$('toast');el.textContent=t;el.classList.add('on');clearTimeout(msg.timer);msg.timer=setTimeout(()=>el.classList.remove('on'),3000);};
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{localOK=false;msg('Browser storage is unavailable. Export your plan from Saved routes.');}}
const act=(id,label,cls='btn',more='')=>`<button class="${cls}" data-action="${id}" ${more}>${label}</button>`;
function commit(f,message){undoState=clone({draft:plan(),p:state.p});f();ranking=null;suggestLimit=8;persist();render();if(message)msg(message);}
function show(k,title,html,mode){dialogMode=mode;$('dialogkicker').textContent=k;$('dialogtitle').textContent=title;$('dialogbody').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();$('dialog').scrollTop=0;}
function close(){if($('dialog').open)$('dialog').close();}
function go(t){if(t==='saved'&&tab==='walk'){StepBuilder.openSaved();return;}tab=t;document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===t));render();}
function currentLabel(){const ref=TRIP.routes.find(r=>r.id===plan().base);const same=JSON.stringify(stops().map(s=>[s.id,s.n]))===JSON.stringify(ref.stops)&&!stops().some(s=>s.hotel||s.picks.length);return same?ref.id:'Custom · '+ref.id;}
function reason(v){let a=[];if(v.resortNights)a.push(v.resortNights+' honeymoon-hotel nights');a.push(v.tet===0?'No Tết transfers':v.tet+' Tết transfer'+(v.tet===1?'':'s'));if(v.blossom)a.push('Tokyo blossom window');return a.join(' · ');}
function metric(label,value,detail,symbol){return `<div class="metric"><div class="label">${icon(symbol)}${label}</div><div class="value">${value}</div><small>${detail}</small></div>`;}
const mapClick=id=>{const i=stops().findIndex(s=>s.id===id);i>=0?openStop(i):addStop(id);};
function render(){
 const walking=tab==='walk';document.body.classList.toggle('walking',walking);$('walk').hidden=!walking;
 if(walking){StepBuilder.render(state.p);return;}

 m=evaluate(stops(),state.p);const p=state.p,miss=m.stay.some((s,i)=>i&&!s.leg);
 $('metrics').innerHTML=metric('Estimated cost',miss?'Incomplete':euro(m.total),`of ${euro(p.budget)} for two`,'wallet')+metric('Trip length',m.nights+' nights','of '+(rules.end-rules.start)+' available','moon')+metric('Beach time',m.beach+' nights',m.coasts.length+' coastal bases','sun')+metric('Overnight stops',stops().length,m.countries+' countries','pin')+metric('Transfer time',miss?'Incomplete':m.hours.toFixed(1)+' h',`${stops().length-1} transfers`,'clock');
 $('warnings').innerHTML=m.errors.length?`<div class="warning" role="status"><b>Draft needs attention.</b> ${m.errors.map(esc).join(' ')} ${m.nights!==rules.end-rules.start?act('balance','Balance nights','textbtn'):''}</div>`:'';
 $('builder').hidden=tab!=='builder';$('lower').hidden=tab!=='builder';$('altview').hidden=tab==='builder';
 if(tab==='builder'){
 $('routeid').textContent='CURRENT ROUTE · '+currentLabel().toUpperCase();
 $('stoplist').innerHTML=stops().map((s,i)=>`<button class="stop ${selected===i?'selected':''}" data-stop="${i}"><span class="marker" style="--dot:${AtlasMap.palette[dest[s.id].country]}">${i+1}</span><span><strong>${esc(dest[s.id].name)}</strong><small>${date(m.stay[i].start)} – ${date(m.stay[i].end)}${s.pin?' · Pinned':''}</small></span><span class="pill">${s.n} nights</span><span class="caret">›</span></button>`).join('');
 $('itfoot').textContent=`${stops().length} stops · ${m.errors.length?'Draft':m.fit.toFixed(2)+' / 100 fit'}`;
 $('legend').innerHTML=countryOrder.map(c=>`<span><i class="dot" style="--dot:${AtlasMap.palette[c]}"></i>${c}</span>`).join('');
 AtlasMap.render(stops(),selected,mapClick);
 $('lower').innerHTML=`<section class="panel"><div class="panelhead"><div><div class="eyebrow">BUILD YOUR ROUTE</div><h2>Shape the trip</h2></div>${undoState?act('undo','Undo last change','textbtn'):''}</div><div class="tiles">${[['mix','Mix country blocks','Combine legs from different workbook routes.'],['shift','Move nights','Compare one-night swaps while keeping both flight dates.'],['cost','See cost breakdown','Inspect hotels, transfers and picked outings.']].map(([a,title,sub])=>`<button data-action="${a}" class="tile" style="text-align:left"><strong>${title} ›</strong><small>${sub}</small></button>`).join('')}</div></section>`;
 }else if(tab==='suggestions')suggestions();else savedView();
 $('sheet').href=TRIP.source;
}
const getRanking=()=>ranking??=ranked(plan(),state.p,adaptPins);
function suggestions(){const arr=getRanking();const n=stops().filter(s=>s.pin).length;const items=arr.slice(0,suggestLimit).map((o,i)=>`<article class="rec ${i===0?'best':''}"><div class="main"><strong>${o.draft.base} <span class="tag">${o.m.fit.toFixed(2)} / 100</span>${i===0?' <span class="tag">Best fit</span>':''}${o.adjusted?' <span class="tag">Other nights adapted</span>':''}</strong><div class="path">${o.draft.stops.map(s=>esc(dest[s.id].name)).join(' · ')}</div><small>${euro(o.m.total)} · ${o.m.beach} coastal nights · ${o.draft.stops.length} stops · ${o.m.hours.toFixed(1)} h transfers<br>${esc(reason(o.m))}</small></div>${act('useSuggestion','Use route','btn small',`data-id="${o.draft.base}"`)}</article>`).join('');$('altview').innerHTML=`<section class="panel"><div class="panelhead"><div><div class="eyebrow">ROUTE SUGGESTIONS</div><h2>Routes that fit</h2><p>${arr.length} of ${TRIP.routes.length} routes meet your preferences${n?` and preserve ${n} pinned stay${n===1?'':'s'}`:''}.</p></div>${act('prefs',icon('sliders')+' Preferences')}</div>${n?`<label class="check filters"><input id="adaptPins" type="checkbox" ${adaptPins?'checked':''}> Adapt other nights around pinned stays</label>`:''}${items||'<div class="empty"><b>No matching routes.</b><p>Unpin a stay, widen the budget or relax a required destination. Your current draft is still editable.</p></div>'}${arr.length>suggestLimit?act('more','Show more routes'):''}</section>`;}
function draftLoad(d,p){commit(()=>{state.draft=clone(d);if(p)state.p=clone(p);selected=-1;tab='builder';},'Route loaded');go('builder');AtlasMap.fit($('region').value);close();}
function savedView(){const items=state.saved.map((s,i)=>{const e=evaluate(s.draft.stops,s.p);return `<div class="rec"><div class="main"><strong>${esc(s.name)}</strong><small>${s.draft.stops.length} stops · ${e.nights} nights · ${euro(e.total)} · ${e.errors.length?'Draft':e.fit.toFixed(2)+' fit'} · ${s.draft.base}</small></div>${act('openSaved','Open','btn small',`data-i="${i}"`)}${act('removeSaved','Remove','textbtn',`data-i="${i}"`)}</div>`;}).join('');$('altview').innerHTML=`<section class="panel"><div class="panelhead"><div><div class="eyebrow">YOUR COLLECTION</div><h2>Saved routes</h2><p>${localOK?'Drafts are saved in this browser.':'Browser storage is unavailable.'} Export a route to open it on another device.</p></div><div class="buttons">${act('export','Export current route')}${act('import','Import route')}<input type="file" id="file" hidden accept=".json,application/json"></div></div>${items||'<div class="empty">Choose <b>Save route</b> to keep a named version for comparison.</div>'}</section>`;}
function catalog(search=''){const term=search.toLowerCase().trim();const list=TRIP.routes.filter(r=>(r.id+' '+r.stops.map(([id])=>dest[id].name).join(' ')).toLowerCase().includes(term)).sort((a,b)=>(a.rank||999)-(b.rank||999)||a.id.localeCompare(b.id));const html=list.map(r=>`<div class="listrow"><div class="bet"><strong>${r.id} <span class="tag">${r.rank?'Workbook #'+r.rank:'Outside workbook rules'}</span></strong>${act('useCatalog','Load','btn small',`data-id="${r.id}"`)}</div><div class="desc">${r.stops.map(([id,n])=>`${esc(dest[id].name)} ${n}`).join(' · ')}</div><small>${euro(r.cost)} · ${r.beach} coastal nights</small></div>`).join('')||'<p>No matching route.</p>';if(dialogMode==='catalog'&&$('dialog').open){$('catlist').innerHTML=html;return;}show('WORKBOOK CATALOG','Load a starting route',`<label class="field">Search by route ID or destination<input id="catsearch" type="search" placeholder="R097, Kyoto, Phú Quốc…"></label><p class="hint">Loading a route replaces the current draft and pins. Saved versions stay available.</p><div id="catlist">${html}</div>`,'catalog');}
function preferences(){const p=state.p;
 const fields=[['budget','Total budget for two (€)',1,999999],['extras','Long-haul flights and other extras (€)',0,999999],['coast','Target coastal nights',0,80],['resort','Minimum honeymoon-hotel stay',1,80],['minStops','Target minimum distinct bases',1,80],['maxStops','Target maximum hotel stays',1,80],['tokyo','Tokyo night cap (0 = unlimited)',0,80]];
 const weights=[['beachWeight','Beach time'],['paceWeight','Pace and variety'],['resortWeight','Honeymoon hotel'],['budgetWeight','Value for money'],['timeWeight','Short transfers']];
 const slider=(key,label,v,max,step=1)=>`<label class="field">${label}<span class="range"><input type="range" min="0" max="${max}" step="${step}" data-weight="${key}" value="${v}"><output>${v}</output></span></label>`;
 show('YOUR PRIORITIES','Preferences',`<form id="prefForm"><div class="section"><h3>Budget and pace</h3><div class="fieldgrid">${fields.map(([k,l,min,max])=>`<label class="field">${l}<input type="number" name="${k}" min="${min}" max="${max}" step="1" value="${p[k]}" required></label>`).join('')}</div></div><div class="section"><h3>Scoring weights</h3><div class="fieldgrid">${weights.map(([k,l])=>slider(k,l,p[k],40)).join('')}</div></div><details class="section"><summary>Required and excluded destinations</summary><div class="fieldgrid">${Object.entries(dest).map(([id,d])=>`<label class="field">${esc(d.name)}<select data-destpref="${id}"><option value="">Flexible</option><option value="must" ${p.must.includes(id)?'selected':''}>Must visit</option><option value="avoid" ${p.avoid.includes(id)?'selected':''}>Skip</option></select></label>`).join('')}</div></details><div class="section"><h3>Timing</h3><div class="fieldgrid">${[['moon','Full Moon Party in Ko Phangan'],['sumo','Osaka sumo window'],['blossom','Tokyo blossom window'],['avoidTet','Avoid Tết transfers in Vietnam']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${p[k]?'checked':''}>${l}</label>`).join('')}</div></div><details class="section"><summary>Activity interests</summary><div class="fieldgrid">${TRIP.labels.map((l,i)=>slider('a'+i,l,p.activities[i],5,.5)).join('')}</div></details><div class="bet">${act('resetprefs','Use workbook defaults','textbtn','type="button"')}<button class="btn primary" type="submit">Apply preferences</button></div></form>`,'prefs');}
function dated(url,a,b){if(!safeURL(url))return '';const u=new URL(url);if(u.hostname.match(/(^|\.)booking\.com$/)){u.searchParams.set('checkin',iso(a));u.searchParams.set('checkout',iso(b));u.searchParams.set('group_adults','2');u.searchParams.set('no_rooms','1');}return u.href;}
function openStop(i,keep=false){
 selected=i;if(!keep){activeCat='Activities';query='';venueLimit=18;}const s=stops()[i],d=dest[s.id],st=m.stay[i],h=hotels[st.hotelId];
 const list=Object.entries(hotels).filter(([,h])=>h.base===s.id&&h.eligible).sort((a,b)=>a[1].price-b[1].price);
 if(!list.some(([key])=>key===s.hotel)&&s.hotel)list.unshift([s.hotel,hotels[s.hotel]]);
 const trip=TRIP.daytrips[s.id];
 const stayinfo=`<div class="section"><div class="bet"><span class="tag">${date(st.start)} – ${date(st.end)} · ${esc(d.country)}</span>${act('pin',icon('lock')+(s.pin?' Unpin stay':' Pin stay'),s.pin?'btn primary small':'btn small')}</div><div class="fieldgrid"><label class="field">Nights<input id="editNights" type="number" min="1" max="80" value="${s.n}" ${s.pin?'disabled':''}></label><div class="field">Arrival transfer<small>${st.leg?`${st.leg.hours.toFixed(1)} h · ${euro(st.leg.cost)} for two ${link(st.leg.url,'Source')}`:i?'No modeled connection':'Arrival in Bangkok'}</small></div></div>${s.pin?'<p>Pinned stays retain their nights, hotel and outings in suggestions. Unpin to edit.</p>':''}</div>`;
 const hotel=`<div class="section"><h3>Accommodation</h3><label class="field" style="margin-top:8px">Hotel for this stay<select id="hotelSelect" ${s.pin?'disabled':''}><option value="">Automatic selection</option>${list.map(([id,o])=>`<option value="${id}" ${id===s.hotel?'selected':''}>${esc(o.name)} · ${euro(o.price)}/night${TRIP.resorts[s.id]===id?' · honeymoon shortlist':''}</option>`).join('')}</select></label><p><b>${esc(h.name)}</b><br>${euro(st.room)}/night · ${euro(st.roomTotal)} for ${s.n} nights · ${h.rating??'—'}/10${h.pool?' · Pool':''}</p><div class="links">${link(dated(h.url,st.start,st.end),'Check room and dates')}${link(h.map,'Map')}${link(h.website,'Hotel website')}</div></div>`;
 const removal=i!==0&&i!==stops().length-1&&!s.pin?act('deleteStop','Remove stop','textbtn'):'';
 const picks=s.picks.length?`<div class="section"><h3>Picked for this stay</h3>${s.picks.map(id=>{const o=activities.get(id);return `<div class="listrow bet"><span>${esc(o.name)}</span>${act('pick','Remove','textbtn',`data-place="${id}" ${s.pin?'disabled':''}`)}</div>`;}).join('')}</div>`:'';
 show(`STOP ${i+1} OF ${stops().length}`,d.name,stayinfo+hotel+picks+`<div class="section"><h3>Explore this stop</h3>${trip?`<p>${link(trip.url,trip.name)}</p>`:''}<div class="chips filters">${['Activities','Restaurants','Sights','Shopping'].map(c=>`<button class="chip ${activeCat===c?'active':''}" data-venue="${c}">${c}</button>`).join('')}</div><input id="venuesearch" type="search" placeholder="Search ${esc(d.name)}" aria-label="Search stop options" value="${esc(query)}"><div id="venues"></div></div><div class="bet">${removal}${act('done','Done','btn primary')}</div>`,'stop');venues();AtlasMap.render(stops(),selected,mapClick);
}
function venues(){const s=stops()[selected],arr=PLACES.filter(o=>o.base===s.id&&o.cat===activeCat&&(o.name+' '+o.type).toLowerCase().includes(query.toLowerCase()));$('venues').innerHTML=arr.slice(0,venueLimit).map(o=>{const priced=o.cat==='Activities'&&o.low!==null,price=priced?`${euro(o.low)}${o.high!==null&&o.high!==o.low?'–'+euro(o.high):''} / two`:o.cat==='Restaurants'?'Meals covered by daily allowance':'Price unconfirmed';return `<div class="listrow"><div class="bet"><strong>${esc(o.name)}</strong>${act('pick',s.picks.includes(o.id)?'Picked ✓':'Pick','chip',`data-place="${o.id}" ${s.pin?'disabled':''}`)}</div><div class="desc">${esc([o.type,o.time,price].filter(Boolean).join(' · '))}</div>${o.desc?`<div class="desc">${esc(o.desc)}</div>`:''}<div class="links">${link(o.url,'Source')}${link(o.map,'Map')}${link(o.website,'Website')}${link(o.menu,'Menu')}</div></div>`;}).join('')||'<p class="hint">No matching entries for this stop.</p>';if(arr.length>venueLimit)$('venues').innerHTML+=act('moreVenues','Show more');}
const delta=x=>(x>=0?'+':'−')+euro(Math.abs(x));
function addStop(id=''){insertList=insertions(stops(),id);const destIds=[...new Set(insertions(stops()).map(c=>c.id))];
 const items=insertList.map((c,i)=>{const tmp=evaluate(applyInsert(stops(),c,c.n),state.p);return `<div class="listrow"><div class="bet"><strong>${esc(dest[c.id].name)} · ${c.n} nights</strong>${act('insert','Insert','btn small',`data-i="${i}"`)}</div><div class="desc">Between ${dest[stops()[c.at-1].id].name} and ${dest[stops()[c.at].id].name}. Take ${c.n} nights from ${dest[stops()[c.donor].id].name}. ${delta(tmp.total-m.total)} · ${(tmp.hours-m.hours).toFixed(1)} h change.</div></div>`;}).join('');
 show('EDIT ITINERARY','Add a stop',`<label class="field">Destination<select id="insertFilter"><option value="">All possible stops</option>${[...new Set([...destIds,...(id?[id]:[])])].map(k=>`<option value="${k}" ${k===id?'selected':''}>${esc(dest[k].name)}</option>`).join('')}</select></label><p class="hint">Each option uses two known connections and takes nights from an unpinned neighbor. You can then fine-tune the length.</p>${items||'<div class="empty">No supported insertion with spare nights. Mix country blocks to open another route through this destination.</div>'}${act('mix','Mix country blocks')}`,'add');}
function availableBlocks(c){const map=new Map();for(const r of TRIP.routes){const a=r.stops.filter(([id])=>dest[id].country===c);const key=JSON.stringify(a);if(!map.has(key))map.set(key,{a,id:r.id});}return [...map.values()];}
function openMix(){mix=null;show('EDIT ITINERARY','Mix country blocks',`<div class="fieldgrid"><label class="field">Country<select id="blockCountry">${countryOrder.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field">Block from a workbook route<select id="blockChoice"></select></label></div><div id="blockPreview"></div>`,'mix');blockOptions();}
function blockOptions(){const blocks=availableBlocks($('blockCountry').value);$('blockChoice').innerHTML=blocks.map((b,i)=>`<option value="${i}">${b.id} · ${esc(b.a.map(([id,n])=>dest[id].name+' '+n).join(' / '))}</option>`).join('');previewBlock();}
function previewBlock(){const c=$('blockCountry').value,b=availableBlocks(c)[+$('blockChoice').value];const old=stops().filter(s=>dest[s.id].country===c);const existing=old.map(x=>({...x,used:false}));const block=b.a.map(([id,n])=>{const o=existing.find(s=>!s.used&&s.id===id&&s.n===n);if(o){o.used=true;const {used,...rest}=o;return clone(rest);}return {id,n,hotel:'',picks:[],pin:false};});const before=stops().filter(s=>countryOrder.indexOf(dest[s.id].country)<countryOrder.indexOf(c)),after=stops().filter(s=>countryOrder.indexOf(dest[s.id].country)>countryOrder.indexOf(c));mix=[...clone(before),...block,...clone(after)];const tm=evaluate(mix,state.p);let index=-1;const conflict=old.filter(s=>s.pin).some(p=>{index=block.findIndex((b,i)=>i>index&&b.pin&&b.id===p.id&&b.n===p.n);return index<0;});const missing=tm.stay.some((s,i)=>i&&!s.leg);$('blockPreview').innerHTML=`<div class="section"><h3>${esc(c)} · ${b.a.reduce((n,a)=>n+a[1],0)} nights</h3><p>${b.a.map(([id,n])=>`${esc(dest[id].name)} (${n})`).join(' → ')}</p><p>Whole draft: ${tm.nights} nights · ${missing?'incomplete cost':euro(tm.total)} · ${tm.beach} coastal nights.</p>${conflict?'<p class="warntext">This block would change a pinned stay. Unpin it or choose another block.</p>':''}${tm.errors.map(t=>`<p class="warntext">${esc(t)}</p>`).join('')}${act('applyMix','Use this block','btn primary',conflict||missing?'disabled':'')}</div>`;}
function openShift(){swaps=[];for(let i=0;i<stops().length;i++)for(let j=0;j<stops().length;j++){if(i===j||stops()[i].pin||stops()[j].pin||stops()[i].n<=1||stops()[j].n>=80)continue;const a=clone(stops());a[i].n--;a[j].n++;const v=evaluate(a,state.p);if(v.errors.some(x=>!m.errors.includes(x)))continue;swaps.push({i,j,fit:v.fit,cost:v.total,beach:v.beach});}
 swaps.sort((a,b)=>b.fit-a.fit||a.cost-b.cost);const list=swaps.map((s,i)=>`<div class="listrow bet"><span>${dest[stops()[s.i].id].name} → ${dest[stops()[s.j].id].name}<br><small class="hint">${s.fit.toFixed(2)} fit · ${delta(s.cost-m.total)} · ${s.beach} coastal nights</small></span>${act('applyShift','Move night','btn small',`data-i="${i}"`)}</div>`).join('');show('KEEP YOUR FLIGHT DATES','Move a night',`<p class="hint">One-night swaps ranked by fit, then cost. Pinned stays are kept fixed.</p>${list||'<div class="empty">No swap preserves your current constraints. Unpin a stay or change your preferences.</div>'}`,'shift');}
function costs(){const items=[['Accommodation',m.rooms],['Meals and local transport',m.daily],['Transfers · midpoint',m.travel],['Activities and selected extras',m.options],['Long-haul flights and other extras',state.p.extras],['Daily and holiday adjustments',(m.nights+rules.departure)*rules.buffer+m.tet*rules.tetCost],['Estimated total',m.total]];show('BUDGET FOR TWO','Cost breakdown',`<div class="section">${items.map(([l,v])=>`<div class="listrow bet"><span>${l}</span><strong>${euro(v)}</strong></div>`).join('')}<p>Using the low and high transfer fares gives ${euro(m.lo)}–${euro(m.hi)}. Hotel rates are indicative. Enter long-haul fares under Preferences.</p>${m.unpriced?`<p>${m.unpriced} selected outing(s) have no confirmed price. Add a reserve under Preferences.</p>`:''}</div><div class="section"><h3>Transfers</h3>${m.stay.slice(1).map((s,i)=>`<div class="listrow bet"><span>${dest[stops()[i].id].name} → ${dest[stops()[i+1].id].name}</span><small>${s.leg?`${euro(s.leg.cost)} · ${s.leg.hours.toFixed(1)} h ${link(s.leg.url,'Source')}`:'Missing'}</small></div>`).join('')}</div>`,'cost');}
function method(){show('SOURCE & ASSUMPTIONS','How the model works',`<div class="section"><p>Workbook snapshot dated 24 November 2026. The catalog contains ${TRIP.routes.length} routes, ${Object.keys(dest).length} overnight bases, ${Object.keys(legs).length} directed transfers and ${Object.keys(hotels).length} accommodations. ${link(TRIP.source,'Open source workbook')}</p><p>Suggestions filter the catalog against hard limits and pinned stays, then rank by a weighted average of beach time, pace, price, transfers, hotel quality, activities, restaurants, shopping, sights and honeymoon-hotel fit. Country blocks and stop edits can produce new combinations.</p><p>Coastal nights measure time at a coastal base. Event and blossom windows are planning assumptions. Hotel prices are undated room estimates for two. Automatic accommodation chooses a qualifying honeymoon hotel with the smallest total premium across eligible stays. Explicit hotel choices take precedence.</p><p>Priced activities use the midpoint for two people. Meals have a daily allowance. Shops and sights with unknown prices require a reserve. Edits save in this browser. Export and import a route to move it between devices.</p></div>`,'method');}
function exportPlan(){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify({version:1,draft:plan(),p:state.p},null,2)],{type:'application/json'}));a.href=u;a.download='honeymoon-'+plan().base+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function saveDialog(){show('SAVED ROUTES','Save this route',`<form id="saveForm"><label class="field">Route name<input name="name" type="text" maxlength="80" required value="${esc(currentLabel()+' · '+m.beach+' coastal nights')}"></label><p class="hint">Saves your itinerary, places and preferences together.</p><button class="btn primary">Save version</button></form>`,'save');}
function pick(id){const s=stops()[selected];if(s.pin)return;const scroll=$('dialog').scrollTop;commit(()=>{s.picks=s.picks.includes(id)?s.picks.filter(k=>k!==id):[...s.picks,id];});openStop(selected,true);$('dialog').scrollTop=scroll;}
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
 const stop=e.target.closest('[data-stop]');if(stop){openStop(+stop.dataset.stop);return;}
 const venue=e.target.closest('[data-venue]');if(venue){activeCat=venue.dataset.venue;query='';venueLimit=18;$('venuesearch').value='';document.querySelectorAll('[data-venue]').forEach(el=>el.classList.toggle('active',el===venue));venues();return;}
 const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,i=+b.dataset.i;
 if(a==='close'||a==='done')close();else if(a==='prefs')preferences();else if(a==='save')saveDialog();else if(a==='catalog')catalog();else if(a==='useCatalog')draftLoad(fromRoute(TRIP.routes.find(r=>r.id===b.dataset.id)));
 else if(a==='suggest')go('suggestions');else if(a==='more'){suggestLimit+=12;suggestions();}
 else if(a==='useSuggestion')draftLoad(getRanking().find(r=>r.draft.base===b.dataset.id).draft);
 else if(a==='undo'&&undoState){const back=undoState;undoState=null;state.draft=back.draft;state.p=back.p;ranking=null;selected=-1;persist();render();msg('Change undone');}
 else if(a==='balance'){const newStops=clone(stops());if(!rebalance(newStops,state.p)){msg('Unpin a stay to free enough nights.');return;}commit(()=>plan().stops=newStops,'Nights redistributed');}
 else if(a==='resetprefs'){commit(()=>state.p=clone(defaults),'Workbook preferences restored');preferences();}
 else if(a==='pin'){const s=stops()[selected];commit(()=>{s.pin=!s.pin;if(s.pin&&!s.hotel)s.hotel=m.stay[selected].hotelId;});openStop(selected,true);}
 else if(a==='deleteStop'){close();commit(()=>{stops().splice(selected,1);selected=-1;},'Stop removed. Balance the remaining nights when ready.');}
 else if(a==='pick')pick(b.dataset.place);else if(a==='moreVenues'){venueLimit+=20;venues();}
 else if(a==='add')addStop();else if(a==='insert'){const o=insertList[i];commit(()=>{plan().stops=applyInsert(stops(),o,o.n);selected=o.at;},'Stop inserted');openStop(selected);}
 else if(a==='mix')openMix();else if(a==='applyMix'){close();commit(()=>{plan().stops=mix;selected=-1;},'Country block applied');}
 else if(a==='shift')openShift();else if(a==='applyShift'){const s=swaps[i];close();commit(()=>{stops()[s.i].n--;stops()[s.j].n++;},'One night moved');}
 else if(a==='cost')costs();else if(a==='method')method();else if(a==='openSaved'){const z=state.saved[i];draftLoad(z.draft,z.p);}
 else if(a==='removeSaved'){const z=state.saved[i];show('SAVED ROUTES','Remove saved version?',`<p>${esc(z.name)}</p><div class="buttons">${act('close','Keep version')}${act('confirmRemove','Remove version','btn primary',`data-i="${i}"`)}</div>`,'delete');}
 else if(a==='confirmRemove'){state.saved.splice(i,1);persist();close();render();}else if(a==='export')exportPlan();else if(a==='import')$('file').click();else if(a==='zoomIn')AtlasMap.zoom(.7);else if(a==='zoomOut')AtlasMap.zoom(1.4);else if(a==='fit'){$('region').value='All';AtlasMap.fit();}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-weight]'))e.target.nextElementSibling.value=e.target.value;if(e.target.id==='catsearch')catalog(e.target.value);if(e.target.id==='venuesearch'){query=e.target.value;venueLimit=18;venues();}});
document.addEventListener('change',async e=>{const el=e.target;
 switch(el.id){case 'adaptPins':adaptPins=el.checked;ranking=null;suggestLimit=8;suggestions();break;case 'region':AtlasMap.fit(el.value);break;case 'blockCountry':blockOptions();break;case 'blockChoice':previewBlock();break;case 'insertFilter':addStop(el.value);break;
 case 'editNights':{const n=Number(el.value);if(!el.reportValidity()||!Number.isInteger(n)||n<1||n>80){el.value=stops()[selected].n;return;}if(stops()[selected].pin)return;commit(()=>stops()[selected].n=n);openStop(selected,true);break;}
 case 'hotelSelect':if(!stops()[selected].pin){commit(()=>stops()[selected].hotel=el.value);openStop(selected,true);}break;
 case 'file':{const file=el.files[0];if(!file)return;try{if(file.size>150000)throw Error();const x=JSON.parse(await file.text());if(x.version!==1||!validDraft(x.draft)||!validP(x.p))throw Error();draftLoad(x.draft,x.p);}catch{msg('This file is not a valid Honeymoon Atlas route.');}break;}}
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;
 if(f.id==='saveForm'){const name=f.elements.namedItem('name').value.trim();if(!name)return;state.saved.push({name,draft:clone(plan()),p:clone(state.p)});persist();close();render();msg('Route saved in this browser');}
 if(f.id==='prefForm'){const p=clone(state.p);Object.keys(p).forEach(k=>{const el=f.elements.namedItem(k);if(el)p[k]=el.type==='checkbox'?el.checked:+el.value;});f.querySelectorAll('[data-weight]').forEach(el=>{const k=el.dataset.weight;if(/^a\d+$/.test(k))p.activities[+k.slice(1)]=+el.value;else p[k]=+el.value;});p.must=[];p.avoid=[];f.querySelectorAll('[data-destpref]').forEach(el=>{if(el.value)p[el.value].push(el.dataset.destpref);});if(!validP(p)){msg('Minimum stops must be at or below the maximum.');return;}close();commit(()=>state.p=p,'Preferences applied');}
});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();go('walk');});$('dialog').addEventListener('close',()=>{dialogMode='';});StepBuilder.connect({currentPrefs:()=>state.p,applyPrefs(p){state.p=p;ranking=null;persist();},validatePrefs:validP,notify:msg,openPreferences:preferences,legacy:()=>go('builder'),openWalk:()=>go('walk')});render();
})();
